"""The Boardwright MCP server.

It is the engine's tool surface under the Boardwright name, with
Boardwright's own instructions in front and Boardwright's tools added.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any

from . import __version__, engine, paths, prepare

SERVER_NAME = "boardwright"

PREAMBLE = """This is Boardwright, an AI design assistant for Altium Designer. The
boardwright skill holds the design procedure (schematic, library parts,
ERC, PCB layout, DRC, fab outputs); follow it when one applies. Call
boardwright_info once at the start of a design run: it gives the versions
and the folders for the verified-parts store, the fab profiles and the run
reports. When app_ping finds no bridge, boardwright_start_bridge starts it
in the running Altium; boardwright_doctor checks the whole set-up.
A schematic sheet starts from boardwright_draft_schematic: it lays the
plan out by the drawing conventions and writes the template that
sch_draw_template draws.

A client other than Claude Code is shown a short tool list (the
boardwright tools, tool_guide, tool_catalog, tool_invoke). Every other
tool is still there: find it with tool_catalog, run it with tool_invoke.

Two rules hold for every call:
- Save the target project or document by path. Never save the whole
  workspace (app_save_all): it writes other open projects and can raise
  a modal dialog that blocks the bridge.
- Board and library tools resolve "the active document". Focus the
  target (pcb_focus_board, or open the library by path) before editing.

"""


#: What a client other than Claude Code is shown. GitHub Copilot takes at
#: most 128 tools per request and other clients fewer; the engine has ~570.
#: Nothing is removed: tool_catalog finds any tool and tool_invoke runs it.
SMALL_TOOLSET = ("boardwright_info", "boardwright_start_bridge", "boardwright_doctor",
                 "boardwright_draft_schematic", "tool_guide", "tool_catalog", "tool_invoke")


def wants_full_toolset(client_name: str) -> bool:
    """Claude Code handles the full list (it defers tool schemas); an
    unknown client is treated the same, so nothing changes without a name."""
    return not client_name or "claude" in client_name.lower()


def _client_name(low) -> str:
    try:
        params = low.request_context.session.client_params
        return (params.clientInfo.name or "") if params else ""
    except (LookupError, AttributeError):
        return ""


def _advertise_per_client(low) -> None:
    """Show each client the tool list it can take (see SMALL_TOOLSET).

    An explicit EDA_AGENT_TOOLSET keeps the engine's own choice."""
    if os.environ.get("EDA_AGENT_TOOLSET"):
        return
    import mcp.types as types

    original = low.request_handlers.get(types.ListToolsRequest)
    if original is None:
        return

    async def list_tools(req):
        result = await original(req)  # also fills the call-validation cache
        if req is None or wants_full_toolset(_client_name(low)):
            return result
        tools = [t for t in result.root.tools if t.name in SMALL_TOOLSET]
        return types.ServerResult(types.ListToolsResult(tools=tools))

    low.request_handlers[types.ListToolsRequest] = list_tools


def _count_cards(folder: Path) -> int:
    cards = folder / "cards"
    return sum(1 for _ in cards.glob("*.md")) if cards.is_dir() else 0


def _build_info() -> dict[str, Any]:
    root = paths.install_root()
    if root is None:
        return {"install": "development"}
    stamp = root / "runtime" / "BUILD.json"
    try:
        return json.loads(stamp.read_text(encoding="utf-8-sig"))
    except (OSError, ValueError):
        return {"install": str(root), "build": "unknown"}


def _altium_registered() -> list[dict]:
    """Where Altium installs load the script project from (registry; [] if
    none is found, which some Altium versions show even when registered)."""
    try:
        from eda_agent import cli as engine_cli
        return engine_cli.registered_script_projects()
    except Exception:
        return []


def _run_command(*argv: str, timeout: int = 180) -> dict[str, Any]:
    """Run a Boardwright command in a child process and return its text.

    A child keeps the command's console output off this server's stdout,
    which carries the MCP protocol.
    """
    flags = ["-I"] if paths.install_root() is not None else []
    try:
        r = subprocess.run([sys.executable, *flags, "-m", "boardwright", *argv],
                           # Never hand the child this server's stdin: it is
                           # the MCP channel, and a child reading it hangs.
                           stdin=subprocess.DEVNULL,
                           capture_output=True, text=True, timeout=timeout,
                           encoding="utf-8", errors="replace",
                           creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                           env=dict(os.environ))
    except subprocess.TimeoutExpired:
        return {"ok": False, "exit_code": None,
                "output": f"timed out after {timeout} s"}
    text = "\n".join(part for part in (r.stdout.strip(), r.stderr.strip()) if part)
    return {"ok": r.returncode == 0, "exit_code": r.returncode, "output": text}


def info() -> dict[str, Any]:
    """Versions, folders and store contents, as one dict."""
    dirs = {name: {"path": str(p), "exists": p.is_dir()}
            for name, p in paths.data_dirs().items()}
    fab = sorted(p.stem for p in paths.fab_profiles().glob("*.json")) \
        if paths.fab_profiles().is_dir() else []
    root = paths.install_root()
    return {
        "boardwright": __version__,
        "install_root": str(root) if root else None,
        # The interpreter to run Boardwright commands with (setup, doctor,
        # relaunch): "<python>" -I -m boardwright <command>
        "python": str(Path(sys.executable).resolve()),
        "engine": {"package": engine.ENGINE_PACKAGE,
                   "version": engine.version(),
                   "based_on": engine.ENGINE_UPSTREAM},
        "build": _build_info(),
        "home": str(paths.home()),
        "folders": dirs,
        "script_project": str(paths.script_project()),
        "scripts_deployed": prepare.deployed_build(),
        "altium_registered": _altium_registered(),
        "verified_parts": _count_cards(paths.verified()),
        "fab_profiles": fab,
    }


def register_tools(mcp) -> None:
    @mcp.tool()
    def boardwright_info() -> dict:
        """Boardwright versions and the folders it uses.

        Returns the Boardwright and engine versions, the build stamp, the
        per-user folders (workspace, Altium scripts, verified parts, fab
        profiles, run reports) with whether each exists, how many verified
        parts the store holds and which fab profiles are saved. Call it
        once at the start of a design run instead of guessing paths.
        """
        return info()

    @mcp.tool()
    def boardwright_start_bridge(force: bool = False) -> dict:
        """Start the Boardwright bridge script inside the running Altium.

        Use it when app_ping reports no answer and Altium Designer is open.
        It hands StartMCPServer to Altium the way Altium's own Run Script
        menu does, and does nothing if the bridge already answers (unless
        force=True). It cannot start Altium itself. Ask the user first: it
        runs a script inside their Altium. It names the script project by
        its full path, so nothing has to be registered or opened in Altium
        beforehand. If it fails, the user runs the desktop shortcut "Start
        Boardwright in Altium", or in Altium: File > Open > the
        script_project path from boardwright_info, then File > Run Script >
        Altium_API > Dispatcher.pas > StartMCPServer.
        """
        args = ["relaunch"] + (["--force"] if force else [])
        return _run_command(*args)

    @mcp.tool()
    async def boardwright_draft_schematic(plan_path: str, sheet: str = "",
                                          template_path: str = "", png_path: str = "",
                                          seconds: float = 15.0, seed: int = 1,
                                          pins_path: str = "") -> dict:
        """Lay out a schematic sheet from the DesignPlan: THE first step to
        drawing a sheet. Writes a template for sch_preview_template and
        sch_draw_template and a picture of it; touches no sheet.

        The layout follows the drawing conventions an engineer uses: signal
        flowing left to right, input connectors on the left edge and outputs
        on the right, supply symbols pointing up and ground symbols down,
        shunt parts hung off the line they load (a pull-down under its line,
        a divider stacked on its node, decoupling capacitors in a row by
        their IC), wires that never cross where a route around exists,
        long runs replaced by net labels, every signal net named. The
        engine's template checker scores every candidate, so the draft has
        no shorts and matches the plan's netlist pin by pin.

        Look at the picture before drawing. To change it, edit the template
        file (move a part, reroute a wire) and run sch_preview_template on
        it; draft again with another seed for a different layout.

        Args:
            plan_path: the DesignPlan JSON file (Design Notes/schematic_plan.json).
            sheet: the plan sheet to lay out; empty for the first.
            template_path: where to write the template; default
                schematic_draft.json beside the plan.
            png_path: where to write the picture; default beside the template.
            seconds: the search's time budget (more finds tidier layouts).
            seed: another seed, another layout of the same quality.
            pins_path: symbol pins as JSON instead of reading the libraries
                through the bridge (offline).

        Returns:
            ok, template_path, preview_png, measures (wire length, corners,
            crossings, symbols, labels, area), the checker's errors and
            warnings, sheet_size and notes (a bigger sheet needed, nets
            named by label instead of wired).
        """
        import asyncio as _asyncio

        from .layout import draft as _draft
        from .layout import pins as _pins

        plan_file = Path(plan_path)
        try:
            text = plan_file.read_text(encoding="utf-8-sig")
            plan = json.loads(text)
        except (OSError, ValueError) as exc:
            return {"ok": False, "errors": [f"could not read {plan_path}: {exc}"]}
        try:
            from eda_agent.design.plan import DesignPlan
            DesignPlan.model_validate_json(text)
        except Exception as exc:  # pydantic's ValidationError, kept short
            return {"ok": False, "errors": [f"not a valid DesignPlan: {str(exc)[:800]}"]}
        if pins_path:
            symbols, problems = _pins.read_file(pins_path), []
        else:
            symbols, problems = await _pins.read_from_bridge(_pins.needed(plan, sheet))
        if problems:
            return {"ok": False, "errors": problems}
        out_json = Path(template_path) if template_path else \
            plan_file.with_name("schematic_draft.json" if not sheet
                                else f"schematic_draft_{sheet}.json")
        out_png = png_path or str(out_json.with_suffix(".png"))
        result = await _asyncio.to_thread(_draft, plan, symbols, sheet=sheet,
                                          seconds=max(1.0, min(seconds, 120.0)),
                                          seed=seed, png_path=out_png)
        if result.get("template"):
            out_json.parent.mkdir(parents=True, exist_ok=True)
            out_json.write_text(json.dumps(result["template"], indent=1), encoding="utf-8")
            result["template_path"] = str(out_json)
            del result["template"]
            result["next"] = ("Read preview_png. Then sch_draw_template(template_path="
                              f"{str(out_json)!r}, plan_json=<the plan>, document_path="
                              "<the .SchDoc>) on a sheet with none of these parts.")
        return result

    @mcp.tool()
    def boardwright_doctor(offline: bool = False) -> dict:
        """Check the Boardwright set-up on this PC and the live Altium link.

        Reports the runtime, the data folders, the deployed Altium scripts,
        other Altium servers that would fight over the bridge, and (unless
        offline=True) whether Altium and the bridge answer, each with the
        fix. Read-only.
        """
        return _run_command("doctor", *(["--offline"] if offline else []))


def build():
    """Import the engine, rename its server and add Boardwright's layer."""
    engine.configure()
    from eda_agent import server as engine_server

    mcp = engine_server.mcp
    if getattr(mcp, "_boardwright_built", False):
        return engine_server
    low = mcp._mcp_server
    low.name = SERVER_NAME
    low.version = __version__
    low.instructions = PREAMBLE + (low.instructions or "")
    register_tools(mcp)
    _advertise_per_client(low)
    mcp._boardwright_built = True
    return engine_server


def serve() -> int:
    # The plugin has no setup step: get the PC ready before serving.
    prepare.ensure_ready()
    # After a plugin update, move Copilot to this version's folder.
    from . import cli
    moved = cli.retarget_copilot()
    if moved:
        print(f"boardwright: Copilot now loads {moved}", file=sys.stderr, flush=True)
    return int(build().serve_mcp(no_dashboard=True) or 0)
